local a=GetBot()local b=require(GetScriptDirectory()..'/FuncLib/func_utils')function GetDesire()if ShouldSkipBotThink(GetBot())then return 0 end;local c=false;for d,e in pairs(GetUnitList(UNIT_LIST_ENEMIES))do if b.IsValid(e)and GetUnitToUnitDistance(a,e)<1200 and string.find(e:GetUnitName(),'shadow_shaman_ward')then c=true;break end end;if c then return BOT_MODE_DESIRE_NONE end end